return {
...render(ui, { wrapper: Wrapper, ...renderOptions }),
rerender: (newUi, newValue) => {
const NewWrapper = ({ children }) => (
<context.Provider value={newValue !== undefined ? newValue : value}>
{children}
</context.Provider>
);
return render(newUi, { wrapper: NewWrapper, ...renderOptions });
}
};
