// WITH RAG - permissions are enforced at retrieval time.
async function ragAnswer(question, user) {
  const chunks = await vectorDB.search(question, {
    topK: 10,
    // PRE-filter. The model NEVER SEES documents this user
    // is not allowed to read.
    filter: {
      allowedGroups: { $in: user.groups },
      classification: { $lte: user.clearanceLevel }
    }
  });
  return llm.answer(question, chunks);
}

// WITH A FINE-TUNED MODEL - there is no equivalent.
