// Do the arithmetic before arguing either way.

function fineTuneBreakEven({
  requestsPerMonth,
  fewShotTokens,          // examples you send on EVERY request today
  inputPricePerM,
  trainingCostUSD,
  datasetHours,
  hourlyRate,
  retrainsPerYear = 1     // base model deprecation forces this
}) {
  // What few-shot examples cost you, forever.
  const monthlyPromptCost =
    (requestsPerMonth * fewShotTokens / 1e6) * inputPricePerM;

  // What fine-tuning costs you, up front and recurring.
  const oneOff = trainingCostUSD + datasetHours * hourlyRate;
  const annualRetrain = (trainingCostUSD + datasetHours * 0.3 * hourlyRate)
                        * retrainsPerYear;

  return {
    monthlySavingIfFineTuned: Math.round(monthlyPromptCost),
    upfrontCost: Math.round(oneOff),
    annualRecurringCost: Math.round(annualRetrain),
    breakEvenMonths: +(oneOff / monthlyPromptCost).toFixed(1)
  };
}

