// problem. Presenting this as either/or is itself a weak answer.

async function answerQuestion(question, user) {
  // LAYER 1 - RAG supplies the FACTS.
  //   Fresh, permission-filtered, citable.
  const chunks = await retrieve(question, {
    filter: { allowedGroups: { $in: user.groups } },
    rerank: true,
    topK: 5
  });

  // LAYER 2 - PROMPTING orchestrates.
  //   Grounding rules, abstention path, citation requirement,
  //   output schema, untrusted-data boundary.
  const messages = buildGroundedPrompt({
    system: SUPPORT_SYSTEM_PROMPT,   // cached stable prefix
    chunks,                          // variable, after the breakpoint
    question
  });

  // LAYER 3 - THE FINE-TUNED MODEL supplies the FORM.
  //   Reliable house tone and exact output structure, with no
  //   need for 15 few-shot examples in every single request.
  const res = await fineTunedModel.complete(messages, {
    temperature: 0.2,
    response_format: SUPPORT_SCHEMA
  });

  // And validation catches what none of the three guarantee.
  const check = verifyCitations(res, chunks);
  return check.valid ? res : stripUnverifiedClaims(res, check);
}

