// SIZE: think PER CATEGORY, not total. 10 per category catches a
// real regression; 20 is comfortable.
function sizingGuide(categories) {
  return {
    startToday: categories.length * 4,     // ~35 cases. Do this now.
    firstRelease: categories.length * 12,  // ~110. Enough to gate on.
    mature: categories.length * 30,        // ~270. Beyond this mostly
                                           // costs you run time.
    note: "A hundred well-chosen cases beats ten thousand random ones."
  };
}

// HOLD SOME BACK. If your tuned score climbs and the held-out score
// does not, you have been fitting to the test rather than fixing
// the product.
function splitSet(cases) {
  const shuffled = stableShuffle(cases, "fixed-seed");   // reproducible
  const cut = Math.floor(cases.length * 0.75);
  return {
    // Look at these while iterating.
    dev: shuffled.slice(0, cut),
    // DO NOT LOOK AT THESE. Run them before a release only.
    holdout: shuffled.slice(cut)
  };
}

function overfittingCheck(devScore, holdoutScore, history) {
  const gap = devScore - holdoutScore;
  const gapGrowing = gap > mean(history.map(h => h.gap)) + 0.05;
  return {
    gap,
    warning: gapGrowing
      ? "The gap is widening - you are tuning to the dev set."
      : null
  };
}

// IS THE SET TOO EASY? If you pass 95% and users still complain,
// the set is not measuring what they experience.
async function setHealthCheck(evalRun, productionSignals) {
  return {
    offlinePassRate: evalRun.overall,
    productionComplaintRate: productionSignals.thumbsDownRate,

    // The tell. Go and read the complaints, and turn them into cases.
    mismatch: evalRun.overall > 0.9 && productionSignals.thumbsDownRate > 0.1
      ? "TOO EASY OR MISSING A CATEGORY - mine production for what is missing"
      : null,

    // A category with a suspiciously perfect score usually means the
    // cases in it are trivial.
    suspiciouslyPerfect: Object.entries(evalRun.byCategory)
      .filter(([, rows]) => mean(rows.map(r => r.passRate)) === 1)
      .map(([cat]) => cat),

    // Categories nobody has added to in months drift out of date as
    // the documents change.
    staleCategories: Object.entries(evalRun.byCategory)
      .filter(([, rows]) => daysSince(max(rows.map(r => r.addedAt))) > 120)
      .map(([cat]) => cat)
  };
}

