  //     stale - people change teams daily. Only 8 checks, so it is
  //     cheap, and it is how you avoid the leak that actually
  //     happens.
  const allowed = [];
  for (const c of top) {
    if (await source.canRead(session.userId, c.docId)) allowed.push(c);
    else await queue.push({ job: "reindex_acl", docId: c.docId });
  }
  if (!allowed.length) return sayNotFound();

  // 11. BUILD THE CONTEXT - dedupe near-identical chunks, order so
  //     the strongest are first and last, label each with its
  //     source so citations are possible.
  const context = buildContext(allowed, { maxTokens: 6000 });

