console.log("Can fly:", bat.canFly);
console.log("Nocturnal:", bat.nocturnal);
console.log("Sound:", bat.makeSound());
console.log("Breathe:", bat.breathe());
console.log("Fly:", bat.fly());
console.log("Echolocation:", bat.echolocation());
